css:
.complexitysim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #243240;
    background: linear-gradient(170deg, #f4f1ea 0%, #eef1f0 55%, #e7ece9 100%);
    border-radius: 18px;
}

.complexitysim-container * {
    box-sizing: border-box;
}

.complexitysim-header {
    text-align: center;
    padding: 28px 22px 24px;
    background: linear-gradient(135deg, #103b40 0%, #1c5a5a 55%, #2a6f63 100%);
    color: #f3faf6;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 14px 34px rgba(16, 59, 64, 0.30);
}

.complexitysim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.35rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.complexitysim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f2c46b;
    background: rgba(242, 196, 107, 0.14);
    border: 1px solid rgba(242, 196, 107, 0.40);
    padding: 5px 14px;
    border-radius: 999px;
}

.complexitysim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 1rem;
    line-height: 1.55;
    color: #d6e7e0;
}

.complexitysim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #4b6168;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.complexitysim-period-counter #currentDay,
.complexitysim-period-counter #maxPeriods {
    font-weight: 800;
    color: #1c5a5a;
}

.complexitysim-round-name {
    background: rgba(28, 90, 90, 0.12);
    color: #1c5a5a;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.complexitysim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #a6691b;
    background: rgba(242, 196, 107, 0.22);
    border: 1px solid rgba(166, 105, 27, 0.30);
    padding: 4px 12px;
    border-radius: 999px;
}

.complexitysim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.complexitysim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e0e4e2;
    box-shadow: 0 6px 16px rgba(36, 50, 64, 0.08);
    border-top: 4px solid #1c5a5a;
}

.complexitysim-card-readiness { border-top-color: #2a6f63; }
.complexitysim-card-budget { border-top-color: #3a7bb5; }
.complexitysim-card-time { border-top-color: #c98a2b; }
.complexitysim-card-cred { border-top-color: #8a5cc4; }

.complexitysim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7b80;
}

.complexitysim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f2d33;
    font-variant-numeric: tabular-nums;
}

.complexitysim-card-readiness .complexitysim-value { color: #1c5a5a; }
.complexitysim-card-budget .complexitysim-value { color: #2f6699; }
.complexitysim-card-time .complexitysim-value { color: #b6781f; }
.complexitysim-card-cred .complexitysim-value { color: #74479e; }

.complexitysim-sublabel {
    font-size: 0.75rem;
    color: #7c8b90;
    line-height: 1.35;
}

.complexitysim-readiness-target .complexitysim-value { color: #1f8a5f; }
.complexitysim-budget-over { border-top-color: #d64545; }
.complexitysim-budget-over .complexitysim-value { color: #d64545; }
.complexitysim-time-over { border-top-color: #d64545; }
.complexitysim-time-over .complexitysim-value { color: #d64545; }
.complexitysim-cred-high { border-top-color: #1f8a5f; }
.complexitysim-cred-high .complexitysim-value { color: #1f8a5f; }
.complexitysim-cred-low { border-top-color: #d64545; }
.complexitysim-cred-low .complexitysim-value { color: #d64545; }

.complexitysim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #ffffff;
    border: 1px solid #e0e4e2;
    color: #3a4d54;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    box-shadow: 0 4px 12px rgba(36, 50, 64, 0.06);
}

.complexitysim-budget-bar #budgetBarDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #2f6699;
}

.complexitysim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #c98a2b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 6px 16px rgba(36, 50, 64, 0.08);
}

.complexitysim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.complexitysim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #103b40;
    margin-bottom: 6px;
}

.complexitysim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4d54;
}

.complexitysim-briefing-text strong { color: #1c5a5a; }
.complexitysim-briefing-text em { color: #a6691b; font-style: italic; }

.complexitysim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e0e4e2;
    box-shadow: 0 6px 16px rgba(36, 50, 64, 0.08);
}

.complexitysim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #103b40;
    border-bottom: 2px solid #eaedeb;
    padding-bottom: 8px;
}

.complexitysim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2b3b41;
    margin: 14px 0 6px;
}

.complexitysim-container select,
.complexitysim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c9d2cf;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fbfcfb;
    color: #243240;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.complexitysim-container select:focus,
.complexitysim-container input[type="number"]:focus {
    outline: none;
    border-color: #2a6f63;
    box-shadow: 0 0 0 3px rgba(42, 111, 99, 0.18);
}

.complexitysim-container select option {
    background-color: #ffffff;
    color: #243240;
}

.complexitysim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #c98a2b;
}

.complexitysim-range-readout,
.complexitysim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4b6168;
    margin-top: 4px;
}

.complexitysim-range-readout span:nth-child(2),
.complexitysim-alloc-readout span:nth-child(2) {
    color: #1c5a5a;
    font-weight: 800;
}

.complexitysim-hint {
    font-size: 0.8rem;
    color: #7c8b90;
    margin-top: 4px;
    line-height: 1.4;
}

.complexitysim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.complexitysim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f6f8f6;
    border: 1px solid #dfe6e2;
    border-radius: 9px;
    padding: 8px 12px;
}

.complexitysim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #34474d;
}

.complexitysim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.complexitysim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.complexitysim-container .btn-primary {
    background: linear-gradient(135deg, #1c5a5a 0%, #2a6f63 100%);
    border: none;
    color: #f3faf6;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 8px 18px rgba(28, 90, 90, 0.30);
}

.complexitysim-container .btn-primary:hover {
    filter: brightness(1.08);
}

.complexitysim-container .btn-outline-secondary {
    margin-left: 10px;
    border: 1px solid #c9d2cf;
    color: #4b6168;
    background: transparent;
}

.complexitysim-coach {
    background: linear-gradient(160deg, #103b40 0%, #1b4f4a 100%);
    color: #e7f2ed;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 8px 20px rgba(16, 59, 64, 0.25);
}

.complexitysim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f2c46b;
    margin-bottom: 8px;
}

.complexitysim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.complexitysim-coach-body strong { color: #f2c46b; }
.complexitysim-coach-body em { color: #9fd9c4; font-style: italic; }

.complexitysim-history,
.complexitysim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e0e4e2;
    box-shadow: 0 6px 16px rgba(36, 50, 64, 0.08);
}

.complexitysim-history h3,
.complexitysim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #103b40;
}

.complexitysim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #34474d;
}

.complexitysim-container table#usfHistoryTable th {
    background: #f0f4f2;
    color: #1c5a5a;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #dde5e1;
}

.complexitysim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eaedeb;
    color: #3a4d54;
}

.complexitysim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f9fbfa;
}

.complexitysim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .complexitysim-container {
        padding: 14px;
    }
    .complexitysim-header h1 {
        font-size: 1.7rem;
    }
    .complexitysim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .complexitysim-value {
        font-size: 2rem;
    }
    .complexitysim-clock {
        margin-left: 0;
    }
    .complexitysim-period-counter {
        font-size: 0.88rem;
    }
    .complexitysim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .complexitysim-alloc-row {
        flex-wrap: wrap;
    }
    .complexitysim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .complexitysim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.complexitysim-cm { background:#f4f8f7; color:#12211f; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.complexitysim-cm-head { text-align:center; border-bottom:1px solid #dbe7e3; padding-bottom:14px; margin-bottom:16px; }
.complexitysim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#4f6560; font-weight:700; }
.complexitysim-cm-scorewrap { margin:8px 0 2px; }
.complexitysim-cm-score { font-size:52px; font-weight:800; color:#2a6f63; line-height:1; }
.complexitysim-cm-score-max { font-size:20px; color:#84958f; font-weight:600; }
.complexitysim-cm-grade { font-size:19px; font-weight:700; color:#12211f; margin-top:4px; }
.complexitysim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.complexitysim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.complexitysim-cm-met { background:#cfeee1; color:#1c6b4f; }
.complexitysim-cm-fail { background:#f7dfd9; color:#a4392a; }
.complexitysim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.complexitysim-cm-metric { background:#e8f1ed; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.complexitysim-cm-metric-val { font-size:22px; font-weight:800; color:#12211f; }
.complexitysim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#4f6560; margin-top:3px; }
.complexitysim-cm-insights { background:#e8f1ed; border-radius:10px; padding:14px 18px; }
.complexitysim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#4f6560; font-weight:700; margin-bottom:8px; }
.complexitysim-cm-insights ul { margin:0; padding-left:18px; }
.complexitysim-cm-insights li { font-size:14px; line-height:1.5; color:#28382f; margin-bottom:7px; }

