(function() {
    'use strict';

    class ComplexityAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Complexity Coach`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Meridian Infrastructure Group, AUD).
            this.LEADERS = 120;            // senior-leader cohort
            this.BASELINE = 2.4;           // complexity-readiness baseline (/5)
            this.TARGET = 3.6;             // board-set 12-month target (/5)
            this.BUDGET_CAP = 2.4;         // A$2.4M fixed program budget, no contingency
            this.PER_LEADER = 0.02;        // ~A$20,000 per leader all-in (A$M)
            this.AMP_COST = 0.038;         // A$38,000 per leader external AMP (A$M)
            this.COACH_COST = 0.009;       // A$9,000 per leader, 6-session engagement (A$M)
            this.COACH_POOL = 40;          // pool covers 40 of 120 at behaviour-changing depth
            this.TIME_TOLERANCE = 12;      // ~12 days/leader off-the-job the business tolerates
            this.KEY_LEADER_LOSS = 0.6;    // A$600k+ to lose a key senior leader (A$M)
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    readiness: 2.4,          // cohort complexity-readiness (/5), starts at baseline
                    budgetUsed: 0,           // A$M committed of the 2.4 cap
                    timeLoad: 0,             // avg days/leader off-the-job
                    cred: 25,                // board credibility in the 12-month read-out (0–100)
                    segmented: false,
                    bustBudget: false,
                    dilutedCoaching: false,
                    cavedToSponsor: false,
                    satisfactionOnly: false,
                    readinessHistory: [2.4],
                    credHistory: [25],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately WRONG-LEANING mix
                // (training framing, prestige AMP, equal coaching, satisfaction read-out)
                // so a blind click-through cannot auto-win.
                state.decisions = {
                    nature: `skills`,
                    capacity: `cognitive`,
                    segment: `uniform`,
                    target: 40,
                    action: 0.4,
                    coaching: 0.4,
                    workshops: 0.6,
                    amp: 1.0,
                    balance: `breadth`,
                    rule: `equal`,
                    depth: `dilute`,
                    peer: 10,
                    lobby: `cave`,
                    measure: `satisfaction`,
                    indicators: `lagging`,
                    sustain: `none`,
                    pitch: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const na = document.getElementById(`natureInput`);
                const ca = document.getElementById(`capacityInput`);
                const se = document.getElementById(`segmentInput`);
                const tg = document.getElementById(`targetInput`);
                if (na) decisions.nature = na.value;
                if (ca) decisions.capacity = ca.value;
                if (se) decisions.segment = se.value;
                if (tg) decisions.target = parseInt(tg.value, 10);
                if (!Number.isFinite(decisions.target) || decisions.target < 0 || decisions.target > 100) {
                    warn(`warn_target_range`); return false;
                }
            } else if (round === 2) {
                const ac = document.getElementById(`actionInput`);
                const co = document.getElementById(`coachingInput`);
                const wo = document.getElementById(`workshopsInput`);
                const am = document.getElementById(`ampInput`);
                const ba = document.getElementById(`balanceInput`);
                if (ac) decisions.action = parseFloat(ac.value);
                if (co) decisions.coaching = parseFloat(co.value);
                if (wo) decisions.workshops = parseFloat(wo.value);
                if (am) decisions.amp = parseFloat(am.value);
                if (ba) decisions.balance = ba.value;
                const parts = [decisions.action, decisions.coaching, decisions.workshops, decisions.amp];
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.action + decisions.coaching + decisions.workshops + decisions.amp) * 100) / 100;
                if (total <= 0) {
                    warn(`warn_alloc_empty`); return false;
                }
                // The cap is hard — over-spend is allowed to be ENTERED so the budget-bust
                // error is playable, but flagged so the learner sees it.
                if (total > this.BUDGET_CAP + 0.001) {
                    warn(`warn_alloc_over`);
                }
            } else if (round === 3) {
                const ru = document.getElementById(`ruleInput`);
                const de = document.getElementById(`depthInput`);
                const pe = document.getElementById(`peerInput`);
                const lo = document.getElementById(`lobbyInput`);
                if (ru) decisions.rule = ru.value;
                if (de) decisions.depth = de.value;
                if (pe) decisions.peer = parseInt(pe.value, 10);
                if (lo) decisions.lobby = lo.value;
                if (!Number.isFinite(decisions.peer) || decisions.peer < 0) {
                    warn(`warn_peer_value`); return false;
                }
            } else if (round === 4) {
                const me = document.getElementById(`measureInput`);
                const ind = document.getElementById(`indicatorsInput`);
                const su = document.getElementById(`sustainInput`);
                const pi = document.getElementById(`pitchInput`);
                if (me) decisions.measure = me.value;
                if (ind) decisions.indicators = ind.value;
                if (su) decisions.sustain = su.value;
                if (pi) decisions.pitch = parseInt(pi.value, 10);
                if (!Number.isFinite(decisions.pitch) || decisions.pitch < 0 || decisions.pitch > 100) {
                    warn(`warn_pitch_range`); return false;
                }
            }
            this._updateBriefing(state);
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let readinessDelta = 0, credDelta = 0, spend = 0, timeDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose: developmental gap, not skills/training (Common Error 1).
                switch (d.nature) {
                    case `developmental`: readinessDelta += 0.10; credDelta += 10; coachKey = `coach_r1_developmental`; break;
                    case `motivation`: credDelta -= 4; coachKey = `coach_r1_motivation`; break;
                    case `skills`: readinessDelta += 0.02; credDelta -= 6; coachKey = `coach_r1_skills`; break;
                }
                // Which capacity is missing — both cognitive AND emotional.
                switch (d.capacity) {
                    case `both`: readinessDelta += 0.06; credDelta += 8; if (d.nature === `developmental`) coachKey = `coach_r1_sharp`; break;
                    case `cognitive`: readinessDelta += 0.02; credDelta += 2; break;
                    case `technical`: readinessDelta -= 0.02; credDelta -= 6; coachKey = `coach_r1_technical`; break;
                }
                // Segment vs one-size-fits-all (Pedagogical Objective 1).
                if (d.segment === `segmented`) { ds.segmented = true; credDelta += 8; readinessDelta += 0.04; }
                else { credDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r1_uniform` : coachKey; }
                // Sharpness of the target behaviour — observable on live trade-offs.
                if (d.target >= 60) { credDelta += 6; }
                else if (d.target <= 25) { credDelta -= 5; coachKey = `coach_r1_vaguetarget`; }

                summaryKey = (d.nature === `developmental` && d.capacity === `both` && d.segment === `segmented`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Design the costed mix within the A$2.4M cap (Common Errors 2; 70-20-10 logic).
                const action = d.action, coaching = d.coaching, workshops = d.workshops, amp = d.amp;
                const total = action + coaching + workshops + amp;
                spend = total;

                // 70-20-10: reward weight on action-learning (70%) & coaching (20%) over content (10%) & AMP.
                readinessDelta += action * 0.30 + coaching * 0.26 + workshops * 0.05;
                // The prestige AMP buys brand, not developmental capacity at scale.
                readinessDelta += amp * 0.04;
                credDelta += Math.round(action * 7 + coaching * 6 + workshops * 1 - amp * 2);
                // Time-off-the-job load: action-learning is on-the-job (light); AMP & workshops are heavy.
                timeDelta += action * 1.5 + coaching * 1.0 + workshops * 5.0 + amp * 9.0;

                if (total > this.BUDGET_CAP + 0.001) {
                    // Budget bust — Common Error 2 (prestige AMP blows the cap, no contingency).
                    ds.bustBudget = true;
                    credDelta -= Math.round((total - this.BUDGET_CAP) * 18 + 8);
                    coachKey = (d.balance === `prestige` || amp >= 1.5) ? `coach_r2_amp` : `coach_r2_overbudget`;
                } else {
                    // Living inside the budget is itself credible.
                    credDelta += 6;
                }

                // Breadth vs depth (Pedagogical Objective 2).
                switch (d.balance) {
                    case `depth`: readinessDelta += 0.10; credDelta += 6; if (!ds.bustBudget) coachKey = `coach_r2_depth`; break;
                    case `breadth`: readinessDelta -= 0.04; credDelta -= 2; if (coachKey === `coach_default`) coachKey = `coach_r2_breadth`; break;
                    case `prestige`: ds.bustBudget = ds.bustBudget || amp > 0; credDelta -= 8; break;
                }

                // Inverting 70-20-10 (content-heavy) is weak even inside budget.
                if (workshops + amp > action + coaching && !ds.bustBudget) {
                    credDelta -= 4; if (coachKey === `coach_default` || coachKey === `coach_r2_breadth`) coachKey = `coach_r2_contentheavy`;
                }

                summaryKey = (!ds.bustBudget && d.balance === `depth` && action + coaching >= workshops + amp) ? `sum_r2_good` :
                             (ds.bustBudget ? `sum_r2_overbudget` : `sum_r2_weak`);
            } else if (round === 3) {
                // Allocate scarce coaching under a defensible rule (Common Errors 3 & 4).
                const peerSpend = d.peer / 100;          // slider is in A$0.01M steps → A$M
                spend = peerSpend;

                // Allocation rule.
                switch (d.rule) {
                    case `critical`: readinessDelta += 0.14; credDelta += 12; coachKey = `coach_r3_critical`; break;
                    case `potential`: readinessDelta += 0.08; credDelta += 5; coachKey = `coach_r3_potential`; break;
                    case `equal`: readinessDelta += 0.02; credDelta -= 6; coachKey = `coach_r3_equal`; break;
                    case `sponsor`: readinessDelta -= 0.02; credDelta -= 10; coachKey = `coach_r3_sponsorrule`; break;
                }

                // Depth-for-few vs diluted-for-many (Common Error 3 — one session changes no one).
                if (d.depth === `depth`) {
                    readinessDelta += 0.12; credDelta += 8;
                } else {
                    ds.dilutedCoaching = true; readinessDelta -= 0.06; credDelta -= 8;
                    if (coachKey === `coach_default` || coachKey === `coach_r3_potential`) coachKey = `coach_r3_diluted`;
                }

                // Peer-coaching layer extends reach affordably (but doesn't replace depth).
                if (peerSpend >= 0.10 && peerSpend <= 0.30) { readinessDelta += 0.05; credDelta += 5; }
                else if (peerSpend > 0.30) { credDelta -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_peerover` : coachKey; }
                else if (peerSpend <= 0.001) { credDelta -= 2; }

                // Hold the line against the sponsoring executive (Common Error 4).
                switch (d.lobby) {
                    case `hold`: credDelta += 10; coachKey = `coach_r3_hold`; break;
                    case `transparent`: credDelta += 6; break;
                    case `cave`: ds.cavedToSponsor = true; credDelta -= 12; readinessDelta -= 0.04; coachKey = `coach_r3_caved`; break;
                }

                summaryKey = (d.depth === `depth` && (d.rule === `critical` || d.rule === `potential`) && d.lobby !== `cave`) ? `sum_r3_good` :
                             (ds.dilutedCoaching ? `sum_r3_diluted` : (ds.cavedToSponsor ? `sum_r3_caved` : `sum_r3_weak`));
            } else if (round === 4) {
                // Prove it & sustain it (Common Error 5 — satisfaction not transfer).
                switch (d.measure) {
                    case `behaviour`: readinessDelta += 0.10; credDelta += 16; coachKey = `coach_r4_behaviour`; break;
                    case `completion`: credDelta += 2; coachKey = `coach_r4_completion`; break;
                    case `satisfaction`: ds.satisfactionOnly = true; credDelta -= 12; coachKey = `coach_r4_satisfaction`; break;
                }
                // Connect leading to lagging indicators.
                switch (d.indicators) {
                    case `linked`: credDelta += 10; readinessDelta += 0.04; break;
                    case `lagging`: credDelta -= 2; break;
                    case `leading`: credDelta -= 5; coachKey = (coachKey === `coach_default`) ? `coach_r4_leadingonly` : coachKey; break;
                }
                // Sustain mechanism (transfer & sustainment).
                switch (d.sustain) {
                    case `embed`: readinessDelta += 0.12; credDelta += 12; if (d.measure === `behaviour`) coachKey = `coach_r4_landed`; break;
                    case `refresh`: readinessDelta += 0.02; credDelta += 2; break;
                    case `none`: readinessDelta -= 0.04; credDelta -= 8; coachKey = (coachKey === `coach_r4_behaviour`) ? `coach_r4_nosustain` : coachKey; break;
                }
                // Conviction in the board pitch.
                if (d.pitch >= 60) { credDelta += 6; }
                else if (d.pitch <= 25) { credDelta -= 5; }

                summaryKey = (d.measure === `behaviour` && d.indicators === `linked` && d.sustain === `embed`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Resource accounting.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;
            ds.timeLoad = Math.round((ds.timeLoad + timeDelta) * 10) / 10;

            // Over-running the time envelope erodes credibility (business resists time away).
            if (ds.timeLoad > this.TIME_TOLERANCE) {
                credDelta -= Math.round((ds.timeLoad - this.TIME_TOLERANCE) * 1.2);
            }

            // Apply deltas. Readiness clamps to 1.0–5.0; credibility 0–100.
            ds.readiness = Math.max(1.0, Math.min(5.0, Math.round((ds.readiness + readinessDelta) * 100) / 100));
            ds.cred = Math.max(0, Math.min(100, Math.round(ds.cred + credDelta)));

            ds.readinessHistory.push(ds.readiness);
            ds.credHistory.push(ds.cred);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing(window.mySimulation.state);
            }, 500);

            return {
                period: state.currentPeriod,
                readiness: ds.readiness,
                readinessDelta: Math.round(readinessDelta * 100) / 100,
                cred: ds.cred,
                credDelta: Math.round(credDelta),
                budgetUsed: ds.budgetUsed,
                timeLoad: ds.timeLoad,
                bustBudget: ds.bustBudget,
                dilutedCoaching: ds.dilutedCoaching,
                cavedToSponsor: ds.cavedToSponsor,
                satisfactionOnly: ds.satisfactionOnly,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        _fmtMoney(v) {
            // AUD: English "A$2.40M"; Spanish "2,40 A$" (comma decimal, symbol after).
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const sign = v < 0 ? `-` : ``;
            const abs = Math.abs(v);
            if (lang === `es`) {
                return `${sign}${abs.toFixed(2).replace(`.`, `,`)} A$`;
            }
            return `${sign}A$${abs.toFixed(2)}M`;
        }

        _fmtReadiness(v) {
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const s = Number(v).toFixed(2);
            return lang === `es` ? s.replace(`.`, `,`) : s;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            const self = this;

            uiManager.bind(`readinessDisplay`, `domainState.readiness`, (v) => {
                const card = document.querySelector(`.complexitysim-card-readiness`);
                if (card) card.classList.toggle(`complexitysim-readiness-target`, Number(v) >= self.TARGET);
                return self._fmtReadiness(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.complexitysim-card-budget`);
                if (card) card.classList.toggle(`complexitysim-budget-over`, Number(v) > self.BUDGET_CAP + 0.001);
                return self._fmtMoney(Number(v));
            });
            uiManager.bind(`timeDisplay`, `domainState.timeLoad`, (v) => {
                const card = document.querySelector(`.complexitysim-card-time`);
                if (card) card.classList.toggle(`complexitysim-time-over`, Number(v) > self.TIME_TOLERANCE);
                return Math.round(Number(v) * 10) / 10;
            });
            uiManager.bind(`credDisplay`, `domainState.cred`, (v) => {
                const card = document.querySelector(`.complexitysim-card-cred`);
                if (card) {
                    card.classList.toggle(`complexitysim-cred-high`, Number(v) >= 65);
                    card.classList.toggle(`complexitysim-cred-low`, Number(v) <= 25);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`budgetBarDisplay`, `domainState.budgetUsed`, (v) => {
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.BUDGET_CAP);
            });

            // Target-behaviour slider readout.
            const tg = document.getElementById(`targetInput`);
            const tgReadout = document.getElementById(`targetReadout`);
            if (tg && tgReadout) {
                tgReadout.textContent = tg.value;
                tg.addEventListener(`input`, function() { tgReadout.textContent = tg.value; });
            }

            // Peer-coaching slider readout (A$M, 0.01M steps).
            const pe = document.getElementById(`peerInput`);
            const peReadout = document.getElementById(`peerReadout`);
            const peFmt = function() {
                if (peReadout) peReadout.textContent = self._fmtReadiness((parseInt(pe.value, 10) || 0) / 100);
            };
            if (pe && peReadout) {
                peFmt();
                pe.addEventListener(`input`, peFmt);
            }

            // Intervention-mix live total (cap A$2.40M).
            const allocIds = [`actionInput`, `coachingInput`, `workshopsInput`, `ampInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 100) / 100;
                if (allocReadout) allocReadout.textContent = self._fmtReadiness(total);
                const bar = document.querySelector(`.complexitysim-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP + 0.001) ? `#d64545` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

