        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.readinessHistory.map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : window.mySimulation.t(`chart_round_prefix`) + i));
            // Readiness (/5) scaled ×20 onto the 0–100 axis to sit alongside credibility.
            const readinessScaled = ds.readinessHistory.map((r) => Math.round(r * 20));
            const targetLine = ds.readinessHistory.map(() => Math.round(this.TARGET * 20));
            return {
                complexityChart: {
                    labels: labels,
                    datasets: [
                        { data: readinessScaled },
                        { data: ds.credHistory },
                        { data: targetLine }
                    ]
                }
            };
        }

        _composite(ds) {
            // v1.0.0 composite formula, verbatim — single source of truth.
            const readiness = ds.readiness;
            const cred = Math.round(ds.cred);
            const budgetUsed = ds.budgetUsed;
            const timeLoad = ds.timeLoad;
            const onBudget = budgetUsed <= this.BUDGET_CAP + 0.001;
            const onTime = timeLoad <= this.TIME_TOLERANCE;
            const readinessScore = Math.max(0, Math.min(100, ((readiness - this.BASELINE) / (this.TARGET - this.BASELINE)) * 100));
            const budgetScore = onBudget ? 100 : Math.max(0, 100 - (budgetUsed - this.BUDGET_CAP) * 60);
            const timeScore = onTime ? 100 : Math.max(0, 100 - (timeLoad - this.TIME_TOLERANCE) * 6);
            return Math.round(readinessScore * 0.38 + cred * 0.34 + budgetScore * 0.16 + timeScore * 0.12);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const readiness = ds.readiness;
            const cred = Math.round(ds.cred);
            const budgetUsed = ds.budgetUsed;
            const timeLoad = ds.timeLoad;

            const onBudget = budgetUsed <= this.BUDGET_CAP + 0.001;
            const onTime = timeLoad <= this.TIME_TOLERANCE;
            const hitTarget = readiness >= this.TARGET;
            const credible = cred >= 60;

            // Composite: progress toward target, board credibility, budget & time discipline.
            const composite = this._composite(ds);

            let performanceKey = `grade_gap`;
            if (hitTarget && credible && onBudget && composite >= 78) performanceKey = `grade_built`;
            else if (credible && onBudget && readiness >= 3.2) performanceKey = `grade_progress`;
            else if (!onBudget) performanceKey = `grade_budget`;
            else if (ds.satisfactionOnly || (ds.dilutedCoaching && ds.cavedToSponsor)) performanceKey = `grade_activity`;
            else if (composite >= 55) performanceKey = `grade_mixed`;
            const met = hitTarget && credible && onBudget && composite >= 78;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && credible && onBudget) insights.push(window.mySimulation.t(`insight_built`));
            else if (!onBudget) insights.push(window.mySimulation.t(`insight_overbudget`));
            else if (ds.satisfactionOnly) insights.push(window.mySimulation.t(`insight_satisfaction`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.dilutedCoaching) insights.push(window.mySimulation.t(`insight_diluted`));
            if (ds.cavedToSponsor) insights.push(window.mySimulation.t(`insight_caved`));
            if (!onTime) insights.push(window.mySimulation.t(`insight_time`));
            if (!ds.segmented) insights.push(window.mySimulation.t(`insight_uniform`));
            if (hitTarget && credible) insights.push(window.mySimulation.t(`insight_transfer`));

            return {
                readiness: readiness,
                cred: cred,
                budgetUsed: budgetUsed,
                timeLoad: timeLoad,
                onBudget: onBudget,
                onTime: onTime,
                hitTarget: hitTarget,
                credible: credible,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                bustBudget: !!ds.bustBudget,
                satisfactionOnly: !!ds.satisfactionOnly,
                dilutedCoaching: !!ds.dilutedCoaching,
                cavedToSponsor: !!ds.cavedToSponsor,
                segmented: !!ds.segmented,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="complexitysim-cm-badge ` + (s.met ? `complexitysim-cm-met` : `complexitysim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.bustBudget) badges.push(`<span class="complexitysim-cm-badge complexitysim-cm-fail">` + t(`cm_fail_budget`) + `</span>`);
            if (s.satisfactionOnly) badges.push(`<span class="complexitysim-cm-badge complexitysim-cm-fail">` + t(`cm_fail_satisfaction`) + `</span>`);
            if (s.dilutedCoaching) badges.push(`<span class="complexitysim-cm-badge complexitysim-cm-fail">` + t(`cm_fail_diluted`) + `</span>`);
            if (s.cavedToSponsor) badges.push(`<span class="complexitysim-cm-badge complexitysim-cm-fail">` + t(`cm_fail_caved`) + `</span>`);
            const kpi = (label, val) => `<div class="complexitysim-cm-metric"><div class="complexitysim-cm-metric-val">` + val + `</div><div class="complexitysim-cm-metric-lbl">` + label + `</div></div>`;
            const rd = (s.readiness != null) ? this._fmtReadiness(s.readiness) : `0`;
            const bg = (s.budgetUsed != null) ? this._fmtMoney(s.budgetUsed) : ``;
            const kpis = kpi(t(`cm_readiness`), rd + ` / 5`)
                + kpi(t(`cm_cred`), (s.cred != null ? Math.round(s.cred) : 0))
                + kpi(t(`cm_budget`), bg)
                + kpi(t(`cm_time`), (s.timeLoad != null ? Math.round(s.timeLoad * 10) / 10 : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="complexitysim-cm">`
                + `<div class="complexitysim-cm-head"><div class="complexitysim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="complexitysim-cm-scorewrap"><span class="complexitysim-cm-score">` + score + `</span><span class="complexitysim-cm-score-max">/100</span></div>`
                + `<div class="complexitysim-cm-grade">` + grade + `</div>`
                + `<div class="complexitysim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="complexitysim-cm-metrics">` + kpis + `</div>`
                + `<div class="complexitysim-cm-insights"><div class="complexitysim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.bustBudget) return window.mySimulation.t(`hint_budget`);
            if (ds.cavedToSponsor) return window.mySimulation.t(`hint_caved`);
            if (ds.dilutedCoaching && state.currentPeriod >= 3) return window.mySimulation.t(`hint_diluted`);
            if (ds.satisfactionOnly) return window.mySimulation.t(`hint_satisfaction`);
            if (ds.timeLoad > this.TIME_TOLERANCE) return window.mySimulation.t(`hint_time`);
            if (ds.readiness >= this.TARGET && ds.cred >= 60) return window.mySimulation.t(`hint_strong`);
            if (state.currentPeriod >= 3 && ds.readiness < 3.0) return window.mySimulation.t(`hint_readiness`);
            return null;
        }

